// Normalise NIPs and drop anything that fails the checksum before we spend a request.
const cfg = $('Set API and Columns').first().json;
const col = cfg.nipColumn || 'NIP';

function checksumOk(nip) {
  if (!/^\d{10}$/.test(nip)) return false;
  const w = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  return w.reduce((a, x, i) => a + x * Number(nip[i]), 0) % 11 === Number(nip[9]);
}

return $input.all().map(item => {
  const row = item.json;
  const nip = String(row[col] ?? '').replace(/\D/g, '');
  return { json: { ...row, nip, nip_valid: checksumOk(nip) } };
});

function findDeep(obj, key, depth) {
  depth = depth || 0;
  if (obj == null || depth > 8) return null;
  if (Array.isArray(obj)) {
    for (const el of obj) { const r = findDeep(el, key, depth + 1); if (r != null) return r; }
    return null;
  }
  if (typeof obj !== 'object') return null;
  if (Object.prototype.hasOwnProperty.call(obj, key)) return obj[key];
  for (const k of Object.keys(obj)) {
    const r = findDeep(obj[k], key, depth + 1);
    if (r != null) return r;
  }
  return null;
}

function people(node) {
  // Board members and partners live under different keys depending on the legal
  // form. Collect anything that looks like a person and de-duplicate.
  const out = [];
  (function walk(o, depth) {
    if (o == null || depth > 9) return;
    if (Array.isArray(o)) { o.forEach(x => walk(x, depth + 1)); return; }
    if (typeof o !== 'object') return;
    const raw = o.imiona || o.imie || o.nazwiskoINazwaPodmiotu?.imiona;
    // KRS zwraca imiona jako tablice obiektow albo stringow, zaleznie od formy prawnej.
    const flat = v => {
      if (v == null) return '';
      if (typeof v === 'string') return v;
      if (Array.isArray(v)) return v.map(flat).filter(Boolean).join(' ');
      if (typeof v === 'object') {
        const s = Object.values(v).find(x => typeof x === 'string');
        return s || '';
      }
      return String(v);
    };
    const first = flat(raw);
    const last  = o.nazwisko || o.nazwiskoINazwaPodmiotu?.nazwisko || o.nazwa;
    if (last) {
      const name = [first, flat(last)].filter(Boolean).join(' ').trim();
      const role = o.funkcjaWOrganie || o.funkcja || o.stanowisko || '';
      if (name) out.push(role ? `${name} (${role})` : name);
    }
    Object.keys(o).forEach(k => walk(o[k], depth + 1));
  })(node, 0);
  return [...new Set(out)];
}// Combine both registries into one flat row per company.
const cfg  = $('Set API and Columns').first().json;
const src  = $('Normalize and Validate NIPs').all().map(i => i.json);
const vat  = $('Fetch VAT White List').all().map(i => i.json);
const krs  = $('Fetch KRS Register').all().map(i => i.json);

const out = [];
for (let i = 0; i < src.length; i++) {
  const s = src[i];
  const subject = vat[i]?.result?.subject || null;
  const odpis = krs[i]?.odpis || null;

  const dane   = odpis ? findDeep(odpis, 'danePodmiotu') : null;
  const header = odpis ? findDeep(odpis, 'naglowekA') : null;
  const addr   = odpis ? (findDeep(odpis, 'adres') || findDeep(odpis, 'siedziba')) : null;
  const pkd    = odpis ? findDeep(odpis, 'przedmiotDzialalnosci') : null;

  const pkdMain = pkd
    ? (findDeep(pkd, 'przedmiotPrzewazajacejDzialalnosci') || findDeep(pkd, 'kodDzial'))
    : null;

  const row = {
    // The sheet is matched on this column, so the NIP goes out under the header
    // the user actually has — and ONLY under that name. Emitting a second copy
    // (e.g. a lowercase `nip`) makes Google Sheets create a stray column and the
    // Update Row call fails with a bad request.
    [cfg.nipColumn || 'NIP']: s.nip,
    nip_valid: s.nip_valid,

    // From the VAT register
    vat_status: subject?.statusVat || (s.nip_valid ? 'NOT_FOUND' : 'INVALID_NIP'),
    name_vat: subject?.name || '',
    regon: subject?.regon || findDeep(dane, 'regon') || '',
    krs: subject?.krs || header?.numerKRS || '',
    address_vat: subject?.workingAddress || subject?.residenceAddress || '',
    bank_accounts: (function () {
      const a = Array.isArray(subject?.accountNumbers) ? subject.accountNumbers : [];
      if (!a.length) return '';
      const MAX = Number(cfg.maxAccounts || 5);
      const shown = a.slice(0, MAX).join(' | ');
      return a.length > MAX ? `${shown} | (+${a.length - MAX} more)` : shown;
    })(),
    vat_registered_since: subject?.registrationLegalDate || '',

    // From the court register
    legal_form: dane ? (dane.formaPrawna || '') : '',
    name_krs: dane ? (dane.nazwa || '') : '',
    krs_registered_since: header?.dataRejestracjiWKRS || '',
    krs_state_as_of: header?.stanZDnia || '',
    people: odpis ? people(findDeep(odpis, 'dzial2') || odpis).slice(0, 12).join(' | ') : '',
    pkd_main: (function () {
      const p = Array.isArray(pkdMain) ? pkdMain[0] : pkdMain;
      if (!p) return '';
      if (typeof p === 'string') return p;
      const code = [p.kodDzial, p.kodKlasa, p.kodPodklasa].filter(Boolean).join('.');
      return [code, p.opis || p.nazwa].filter(Boolean).join(' — ').slice(0, 160);
    })(),
    address_krs: addr ? Object.values(addr).filter(v => typeof v === 'string').join(', ') : '',

    checked_at: new Date().toISOString().slice(0, 19).replace('T', ' '),
  };

  // Google Sheets rejects mixed types in auto-mapped updates (a boolean in one
  // column and text in the next is enough for a bad request). Everything goes to
  // the sheet as a string; nulls become empty cells rather than the word "null".
  for (const k of Object.keys(row)) {
    const v = row[k];
    row[k] = v === null || v === undefined ? '' : String(v).slice(0, 2000);
  }

  out.push({ json: row });
}
return out;
